function reader(){var s=N.data.stories.find(function(x){return x.id===state.selectedStory;})||N.data.stories[0];var heads=['Den sista expeditionen','Spåren på bergssluttningen','Frågor och teorier'];var paragraphs=[['Vinterskymningen hade redan lagt sig över bergssluttningen när expeditionens sista kända etapp inleddes. Vind, kyla och svår terräng skulle bli avgörande delar av berättelsen.','Den här läsvyn är exempeltext för designlaboratoriet, inte en historiskt verifierad redogörelse. Syftet är att kunna jämföra läsbarhet, källhantering, kapitelindelning och typografi.','När ett källmaterial presenteras behöver det gå att följa vad som är observation, tolkning och osäkerhet. En tydlig källpanel kan hjälpa utan att störa själva läsningen.'],['En tidslinje ger läsaren orientering. En dossier ger detaljer. Båda behövs, men de kan presenteras på många olika sätt.','I detta kapitel kan du testa fotnotspanelen, öka textstorleken, markera en läsposition och växla fokusläge. Allt sparas endast i din egen webbläsare.'],['Flera möjliga förklaringar kan beskrivas sida vid sida utan att en av dem förklaras bevisad.','Designstudion används för att hitta lämplig form för sådan osäkerhet: graf, källkort, tidslinje eller redaktionellt berättande.']];return subhead('Läsaren','Kapitel, fotnoter, läsro och typografi med riktig interaktion.')+slot('readerTools',readerToolsMarkup(variant('readerTools'),false))+slot('reader',readerPageMarkup(s,variant('reader'),false,runtime.chapter,paragraphs,heads,runtime.readerFoot));}
function graphMarkup(nodes,mode,mini){
 var positions=nodes.map(function(n,i){var x=n.x,y=n.y;if(mode===3){x=15+i*17;y=18+i*15;}if(mode===4){var angle=(i-1)*Math.PI*2/Math.max(1,nodes.length-1);x=i?50+32*Math.cos(angle):50;y=i?50+32*Math.sin(angle):50;}if(mode===1){x=12+i*18;y=20+(i%2)*50;}if(mode===2){x=15+(i%3)*35;y=19+Math.floor(i/3)*55;}return {x:x,y:y};});
 var edges=positions.slice(1).map(function(n){return '<line x1="'+positions[0].x+'" y1="'+positions[0].y+'" x2="'+n.x+'" y2="'+n.y+'"/>';}).join('');
 var plain=mode===5||mode===7;
 return '<div class="nexus-graph graph-mode-'+mode+(mini?' graph-mini':'')+'">'+(plain?'<div class="nexus-graph-list">'+nodes.map(function(n,i){return '<div class="nexus-graph-list-item" '+(mini?'':'data-node="'+attr(n.id)+'" role="button" tabindex="0"')+'><b>'+(i?'◇':'✳')+'</b><span>'+esc(n.id)+'</span><small>'+esc(n.kind)+'</small></div>';}).join('')+'</div>':'<div class="graph-box"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><g stroke="var(--accent)" stroke-opacity=".5" stroke-width=".5">'+edges+'</g></svg>'+nodes.map(function(n,i){return '<button class="graph-node '+(i===0?'main-node':'')+'" style="left:'+positions[i].x+'%;top:'+positions[i].y+'%" '+(mini?'disabled':'data-node="'+attr(n.id)+'"')+'>'+esc(n.id)+'</button>';}).join('')+'</div>')+(mode===6?'<aside class="graph-inspector"><small>VALT OBJEKT</small><strong>'+esc(nodes[0].id)+'</strong><p>Relationer och metadata</p></aside>':'')+'</div>';
}
