 return '<div class="knowledge-layout knowledge-mode-'+mode+(mini?' knowledge-mini':'')+'">'+special+(showGraph?graphMarkup(nodes,mini?0:variant('graph'),mini):'')+'<div class="knowledge-items">'+cards+'</div></div>';
