function layoutPanel(){return sheetHead('Ordna startsidan','Flytta eller dölj modulerna. Dina val sparas direkt.')+'<div class="stack">'+state.order.map(function(id,i){var m=N.data.modules.find(function(x){return x.id===id;});if(!m)return '';var hidden=state.hidden.includes(id);return '<div class="card layout-item" style="display:flex;align-items:center;gap:8px"><span style="font-size:24px;color:var(--accent)">'+m.icon+'</span><div style="flex:1;min-width:0"><strong style="font-size:12px">'+esc(m.name)+'</strong><small style="display:block;color:var(--muted)">'+(hidden?'Dold':'Visas på startsidan')+'</small></div><button class="mini-btn" data-shift="'+id+'" data-direction="-1" aria-label="Flytta upp" '+(i===0?'disabled':'')+'>↑</button><button class="mini-btn" data-shift="'+id+'" data-direction="1" aria-label="Flytta ner" '+(i===state.order.length-1?'disabled':'')+'>↓</button><button class="mini-btn" data-toggle-module="'+id+'">'+(hidden?'Visa':'Dölj')+'</button></div>';}).join('')+'</div><div class="control-row" style="margin-top:17px">'+button('Klar','close','primary')+'</div>';}
