 var title=esc(m.title),art='<div class="detail-hero" style="background:'+m.poster+'"><h2>'+title+'</h2></div>';
 var genres=(m.genres||[]).map(function(g){return '<span class="chip">'+esc(g)+'</span>';}).join('');
