function searchResults(q){q=(q||'').toLocaleLowerCase();var arr=N.views.map(function(v){return {name:v.name,sub:'Vy',action:'data-go="'+v.id+'"'};}).concat(N.data.media.map(function(m){return {name:m.title,sub:m.type,action:'data-open-media="'+m.id+'"'};}),N.data.stories.map(function(s){return {name:s.title,sub:'Berättelse',action:'data-open-story="'+s.id+'"'};}),N.data.files.map(function(f,i){return {name:f.name,sub:'Arkivfil',action:'data-file="'+i+'"'};}));return '<div class="simple-list">'+arr.filter(function(x){return x.name.toLowerCase().includes(q);}).slice(0,12).map(function(x){return '<button class="builder-item" '+x.action+'><b style="flex:1">'+esc(x.name)+'</b><small>'+esc(x.sub)+'</small>↗</button>';}).join('')+'</div>';}
function quickPanel(){var items=[['films','Öppna Film & serier'],['reader','Öppna läsaren'],['stories','Utforska berättelser'],['knowledge','Kunskapsgraf'],['files','Hitta dokument'],['research','AI-idéarkiv'],['settings','Mina inställningar']];if(variant('ux001'))items.sort(function(a,b){return (a[0]===state.view?-1:0)-(b[0]===state.view?-1:0);});if(variant('ux001')>1){var current=items.filter(function(x){return x[0]===state.view;});var rest=items.filter(function(x){return x[0]!==state.view;});items=current.concat(rest);}return sheetHead('Snabbåtgärder','Genvägar med din aktuella vy överst.')+'<div class="ux-current">Aktuell vy: <b>'+esc((N.views.find(function(v){return v.id===state.view;})||N.views[0]).name)+'</b></div><div class="builder-grid">'+items.map(function(x){return '<button class="builder-item" data-go="'+x[0]+'"><b>'+x[1]+'</b><span class="num">→</span></button>';}).join('')+'</div>';}
